WFJ.Data.add("quest", {
  [84124] = { "L'eredità del valore", "Torna all'Altare della Reverenza", "Il campione spettrale si arrende e fa cenno verso l'altare.", nil, nil, 0xf7a271bc, 0xb3674d45, 0xa4b52305, nil, nil, "...mm" },
  [84135] = { "Robot da spiaggia", "Usa una roccia o qualcosa di simile per staccare dei pezzi del robot.", "Sulla riva, semiperso tra gli spruzzi del pomeriggio, giace uno strano congegno metallico. Sembra una specie di mech, ma non hai mai visto nulla di simile. Noti sul fianco un'etichetta che recita 'Proprietà della D.E.L.T.A.: Deepsea Exploration and Liquefaction Technologies Alliance'. Individui anche un piccolo scomparto che potresti riuscire ad aprire.", nil, nil, 0x053aeb28, 0xc9fc4eaf, 0x793c2949, nil, nil, "...mm" },
  [84137] = { "Romanticismo meccanico", "Trova un uso per l'Acceleratore di Galleggiamento Guidato", "Ti chiedi perché questo mech sia precipitato qui e a cosa serva questo liquido. Forse puoi usarlo per raggiungere le isole vicine e la piattaforma petrolifera che sembrano collegate a questa misteriosa organizzazione. Quando apri la fiala, un aroma fruttato e leggermente inebriante ti accoglie.", nil, nil, 0xd205336c, 0x49c78274, 0x0952cd8e, nil, nil, "...mm" },
  [84138] = { "Favori gelidi", "Spiega la situazione del libro a Nami, collega del dottor Jurgens, a ⟦Winterspring=Fontefredda⟧.", "Sono l'ingegnere capo, fondatore e ricercatore principale della Deepsea Exploration and Liquefaction Technologies Alliance. Ho quasi finito il mio ultimo esperimento e ho bisogno del tuo aiuto! Sto lavorando a un dispositivo speciale per geolocalizzare dimensioni ricche di risorse.\n\nPer completare la mia costruzione mi serve qualcosa che ho prestato: un libro di formule arcane che ho affidato a una vecchia collega, Nami, che continua il suo lavoro a ⟦Winterspring=Fontefredda⟧.\n\nRecuperami il libro e verrai incluso tra i collaboratori della pubblicazione!", nil, nil, 0x0198a07f, 0x15c2cb1a, 0xf9463973, nil, nil, "...mm" },
  [84146] = { "Il blues della Borsa Rossa", "Ritrova la Borsa Rossa che Nami di ⟦Everlook=Lungavista⟧ ha perso in un incidente con uno zeppelin sopra le ⟦Burning Steppes=Steppe Ardenti⟧.", "Ciò che vuoi è al sicuro, e posso solo sperare che lo stesso valga per ciò che cerco io.\n\nAvevo una borsa rossa contenente degli utensili preziosi che uso per l'elettro-ottica. Ma l'ho persa in un incidente di zeppelin sopra le ⟦Burning Steppes=Steppe Ardenti⟧! La borsa potrebbe essere ancora lì, ma con orchi, ogre e bracconieri ho dovuto sospendere il mio lavoro.\n\nSe riesci a trovarla e a riportarmela, ti lascerò il vecchio libro di Jurgens.", nil, nil, 0x1a8943b8, 0xdc3204cc, 0x7cebd737, nil, nil, "...mm" },
  [84147] = { "Una proposta sincera", "Ottieni 15 Campione di Sangue di ⟦Winterspring=Fontefredda⟧ e 20 monete d'oro e portali, insieme a un paio di ⟦Wildheart Bracers=Bracciali del Cuorselvaggio⟧, a Deliana a ⟦Ironforge=Forgiardente⟧.", "Salute, {class}. Ho qualcosa che potrebbe interessarti.\n\nHo con me un'armatura simile a quella indossata da chi esercita la tua professione, ma di qualità molto superiore. Sarei disposto a scambiarti i bracciali con quelli ordinari in cambio di un piccolo favore.\n\nIl sangue delle fiere glaciali e degli orsi che abitano ⟦Winterspring=Fontefredda⟧ ha proprietà di cui al momento ho bisogno. Portamene un campione consistente insieme ai bracciali e a una piccola somma d'oro. Troverai che lo sforzo ne vale la pena.", nil, nil, 0x5744ae45, 0x8fbd8e2f, 0x9df430b9, nil, nil, "...mm" },
