  [84155] = { "Una proposta sincera", "Ottieni 15 Campione di Veleno di Silitide e 20 monete d'oro e portali, insieme a un paio di ⟦Wildheart Bracers=Bracciali del Cuorselvaggio⟧, a Mokvar a Orgrimmar.", "Salve, {class}! Dal tuo portamento si vede che hai visto e fatto molto in questo mondo. Eppure scommetto che non hai mai visto un pezzo d'armatura come questo.\n\nFammi un piccolo favore e sarò disposto a scambiartelo con un normale paio di bracciali.\n\nMi serve un campione consistente di veleno estratto dai ragni e dagli scorpioni che abitano ⟦Silithus=Silitus⟧. Portamelo insieme a qualche moneta d'oro e farò lo scambio.", nil, nil, 0x5744ae45, 0x1763da64, 0xea675b9d, nil, nil, "...mm" },
