  [84163] = { "Giusto compenso", "Porta una ⟦Wildheart Belt=Cintura del Cuorselvaggio⟧ e un paio di ⟦Wildheart Gloves=Guanti del Cuorselvaggio⟧ a Deliana a ⟦Ironforge=Forgiardente⟧.", "Hai mantenuto la parola e hai portato il dispositivo costruito da Mux. Credo che una ricompensa sia dovuta, se voglio che tu resti interessat<o/a> a salvarmi la pelle. Portami la cintura e il paio di guanti che desideri potenziare. Ti prometto che quelli che ti darò in cambio saranno di gran lunga superiori.", nil, nil, 0x467758ec, 0xaf7ff1c4, 0xce2da401, nil, nil, "...mm" },
