  [84169] = { "Giusto compenso", "Porta una ⟦Dreadmist Belt=Cintura Brumafunesta⟧ e un paio di ⟦Dreadmist Wraps=Mitene Brumafunesta⟧ a Deliana a ⟦Ironforge=Forgiardente⟧.", "Hai mantenuto la parola e hai portato il dispositivo costruito da Mux. Credo che una ricompensa sia dovuta, se voglio che tu resti interessat<o/a> a salvarmi la pelle. Portami la cintura e il paio di guanti che desideri potenziare. Ti prometto che quelli che ti darò in cambio saranno di gran lunga superiori.", nil, nil, 0x467758ec, 0x9687a99f, 0xce2da401, nil, nil, "...mm" },
  [84170] = { "Giusto compenso", "Porta una ⟦Belt of Valor=Cintura del Valore⟧ e un paio di ⟦Gauntlets of Valor=Guanti Lunghi del Valore⟧ a Deliana a ⟦Ironforge=Forgiardente⟧.", "Hai mantenuto la parola e hai portato il dispositivo costruito da Mux. Credo che una ricompensa sia dovuta, se voglio che tu resti interessat<o/a> a salvarmi la pelle. Portami la cintura e i guanti lunghi che desideri potenziare. Ti prometto che quelli che ti darò in cambio saranno di gran lunga superiori.", nil, nil, 0x467758ec, 0xb902f02b, 0x35c57e0b, nil, nil, "...mm" },
  [84171] = { "Giusto compenso", "Porta una ⟦Wildheart Belt=Cintura del Cuorselvaggio⟧ e un paio di ⟦Wildheart Gloves=Guanti del Cuorselvaggio⟧ a Mokvar a Orgrimmar.", "Ti sei dimostrat<o/a> una persona molto affidabile, {name}. Per quanto confidi che mi aiuterai a uscire da questa situazione, sarebbe saggio da parte mia ricompensarti in base alle tue prestazioni.\n\nPer ora scambierò la tua cintura e i tuoi guanti. Se porteremo entrambi a termine l'impresa, ti renderò disponibili anche gli altri pezzi.", nil, nil, 0x467758ec, 0x2338cd92, 0xd0d70463, nil, nil, "...mm" },
