  [84195] = { "Il meglio per ultimo", "Consegna a Deliana il tuo ⟦Wildheart Cowl=Copricapo del Cuorselvaggio⟧ e la tua ⟦Wildheart Vest=Veste del Cuorselvaggio⟧.", "Che storia incredibile, {name}! Hai il mio ringraziamento e la sentita gratitudine di tutti i coinvolti. Ora forse riuscirò a dormire la notte con entrambi gli occhi chiusi.\n\nQuanto alla tua ricompensa, credo di avere qualcosa che ti piacerà molto.", nil, nil, 0x48402900, 0xd8200b75, 0x03db6ed6, nil, nil, "...mm" },
