  [84203] = { "Il meglio per ultimo", "Consegna a Mokvar il tuo ⟦Wildheart Cowl=Copricapo del Cuorselvaggio⟧ e la tua ⟦Wildheart Vest=Veste del Cuorselvaggio⟧.", "Una storia davvero incredibile, {name}! Hai il mio ringraziamento e la sentita gratitudine di tutti i coinvolti, te l'assicuro. Grazie ai tuoi sforzi siamo liberati dagli errori del nostro passato.\n\nQuanto alla tua ricompensa, credo di avere qualcosa che ti sei decisamente guadagnat<o/a> e che apprezzerai davvero.", nil, nil, 0x48402900, 0xa5f70ad7, 0xf3ed443f, nil, nil, "...mm" },
