  [84210] = { "Il meglio per ultimo", "Consegna a Mokvar il tuo ⟦Helm of Valor=Elmo del Valore⟧ e il tuo ⟦Breastplate of Valor=Pettorale Corazzato del Valore⟧.", "Una storia davvero incredibile, {name}! Hai il mio ringraziamento e la sentita gratitudine di tutti i coinvolti, te l'assicuro. Grazie ai tuoi sforzi siamo liberati dagli errori del nostro passato.\n\nQuanto alla tua ricompensa, credo di avere qualcosa che ti sei decisamente guadagnat<o/a> e che apprezzerai davvero.", nil, nil, 0x48402900, 0x88cbb0c8, 0xf3ed443f, nil, nil, "...mm" },
  [84211] = { "La tana del bracconiere", "Recupera il resto dei materiali e torna da Nami a ⟦Everlook=Lungavista⟧.", "Raccogliendo la borsa, noti subito che è quasi vuota. In qualche modo hai l'impressione che Nami non scambierà il libro per la sola borsa. Ma ciò che non è vuoto è l'accampamento. Faresti meglio a difenderti e a tenere gli occhi aperti per altra roba di questo genere.", nil, nil, 0x365bdf4a, 0x9c5b921e, 0xe8f51841, nil, nil, "...mm" },
  [84212] = { "Di corsa col libro", "Torna al laboratorio D.E.L.T.A con il libro che cercava Jurgens.", "Nami ti consegna il libro di Jurgens. Dopo averlo riposto al sicuro, inizi il lungo viaggio di ritorno dall'altra parte del mondo.", nil, nil, 0x4001a614, 0xb93dc5d0, 0x0972fb70, nil, nil, "...mm" },
  [84213] = { "Fuga dallo squarcio", "Usa il Dispositivo di Comunicazione a Distanza per inviare il segnale a Jurgens, alle ⟦Tirisfal Glades=Radure di Tirisfal⟧ o alle ⟦Westfall=Marche Occidentali⟧\r\nPoi, aiutalo a dimostrare le capacità del suo trasmettitore elettrico.", "Unisciti a me in questo storico esperimento e assisti alle meraviglie della mia invenzione! Ho calcolato due luoghi con energia bioflusso geotermica adatta. Con i fasatori ad autobloccaggio manuale, sono pronto a trasportarci alle coordinate all'interno di regioni compatibili.\n\nQuando sei a coordinate compatibili, usa questo transponder remoto per inviarmi il segnale. Configurerò il trasmettitore di curvatura per piegare lo spazio tra qui e là.\n\nQuello che sto dicendo è che ci incontreremo là quando mi dirai che sei pront<o/a>!", nil, nil, 0x24449cae, 0xbca503f9, 0x45659c4e, nil, nil, "...mm" },
  [84318] = { "Ehi!", "Trova il martello scomparso di Orthas al Crocevia di Corrin.", "Ehi! {class}! Sì, proprio tu! Mi hai fatto un bel favore a ridurre in pezzi quel deprimente ammasso di carne in cui me ne vado in giro da tutti questi anni, ma non sento granché la spinta ad andare avanti. Immagino sia perché ho delle 'Faccende Incompiute' da sbrigare prima di potermene andare. Be', zuccone, sei appena stat<o/a> arruolat<o/a> per aiutarmi!\n\nMi serve che tu mi recuperi il martello. Dovrebbe essere da qualche parte al Crocevia di Corrin e sarà difficile non vederlo.\n\nEhi, prendi anche questo. È il mio dente d'oro preferito. Strofinalo quando avrai trovato la mia arma.", nil, nil, 0x0014e5a3, 0x4d04ade1, 0x5edb9620, nil, nil, "...mm" },
  [84319] = { "Oh no, non così!", "Orthas ha bisogno che tu recuperi la sua armatura scomparsa dal cadavere di un abominio da qualche parte nella ⟦Plaguewood=Malaselva⟧.", "Ottimo lavoro con il martello, {class}. Ora tocca alla mia armatura. Mi serve di sicuro per passare all'aldilà.\n\nSolo che si trova nelle, ehm... interiora di una di quelle abominazioni. Lo so, lo so, è chiedere tanto, ma devi capire che un tempo ero un potente thane sotto la montagna! Non posso proprio andarmene sapendo che l'armatura ancestrale del mio clan si sta dissolvendo nel succo gastrico di una gigantesca montagna di carne in putrefazione!", nil, nil, 0x3864f2c9, 0x0ff14544, 0x075b11be, nil, nil, "...mm" },
  [84330] = { "Un pizzico di negromanzia", "Ottieni una Runa Necrotica da ⟦Maleki the Pallid=Maleki il Pallido⟧ a Stratholme, poi trova il cadavere di Nano in decomposizione vicino alla Cripta di Zaeldarr, nel sud-ovest delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Quindi vedi, dobbiamo trovare un cadavere di nano adatto e fargli un po' di rituale per ancorare il mio spirito, così potrò andarmene per la mia strada! Tutta roba perfettamente normale, ovviamente! Ci servirà anche un po' di Runa Necrotica da un tipo negromante, ovviamente. A Stratholme ce n'è uno che si fa chiamare ⟦Maleki the Pallid=Maleki il Pallido⟧. Non aspettarti che sia molto propenso a cedercela di buon grado, ma c'è un rimedio!\n\nPrendimi quella pietra e poi dirigiti alla cripta sotterranea. Lì c'è un cadavere che andrà bene!", nil, nil, 0xe2d2d338, 0x2df4d6f8, 0xb119cbe0, nil, nil, "...mm" },
  [84332] = { "La gratitudine di un thane", nil, "<Senti una voce disincarnata nella tua testa mentre tocchi il piccolo forziere>\n\nNon ti ringrazierò mai abbastanza, {name}. Non è andata come ti aspettavi, senza dubbio! Per non lasciarti troppo amareggiat<o/a>, ho qualcosa per te che non mi serve più e che credo ti sarà utile.\n\nBuona fortuna, {name}. Ah, un'ultima cosa... se un giorno, presto, dovessi vedere in lontananza una gigantesca necropoli fluttuante, al posto tuo me la darei a gambe. Ah!", nil, nil, 0x365c1fc6, nil, 0x13d01d2e, nil, nil, ".m.mm" },
  [84338] = { "Un contratto vincolante", "Consegna il ⟦Thorium Brotherhood Contract=Contratto con la Fratellanza del Torio⟧ a ⟦Lokhtos Darkbargainer=Lokhtos Pattoscuro⟧ se vuoi ricevere il progetto di Sulfuron.", "Il sottoscritto dichiara con la presente che il lingotto di Sulfuron consegnato alla ⟦Thorium Brotherhood=Fratellanza del Torio⟧ (TB Ltd.) è autentico e non una sua imitazione. Il sottoscritto riconosce inoltre che qualsiasi danno <gli/le> derivi dal tentativo di costruire, forgiare, trovare, creare, vendere o mangiare Sulfuras non è responsabilità né colpa di TB Ltd.\n\nFirmando questo contratto, accetti tutti i termini qui elencati.\n\n_________________\n\nFirma", nil, nil, 0xb3e013a8, 0xb4f357b1, 0x9f3945b5, nil, nil, "...mm", nil, nil, 0xc22a16e9, nil, nil },
  [84377] = { "La fine dell'⟦Horde=Orda⟧ Oscura", "Porta la ⟦Head of Rend Blackhand=Testa di Rend Manonera⟧ al ⟦Master Mathias Shaw=Maestro Mathias Shaw⟧ a ⟦Stormwind=Roccavento⟧.", "Il fatto è compiuto. Dal'rend Manonera, Capoguerra dell'⟦Horde=Orda⟧ Oscura, giace morto ai tuoi piedi.\n\nPrendi la sua testa e portala al maestro Shaw.", nil, nil, 0x3409b38a, 0xb41d6d2b, 0x6335af8e, nil, nil, "...mm" },
  [84394] = { "Grande amico della biblioteca", nil, nil, nil, nil, 0xf10ee12c, nil, nil, nil, nil, ".mmmm" },
  [84395] = { "Patate Non Morte", nil, nil, nil, nil, 0xe94bc437, nil, nil, nil, nil, ".mmmm" },
  [84396] = { "Magma o lava?", nil, nil, nil, nil, 0xddd086e3, nil, nil, nil, nil, ".mmmm" },
  [84397] = { "Kalimdor settentrionale - Una guida completa", nil, nil, nil, nil, 0x1b1a6b97, nil, nil, nil, nil, ".mmmm" },
  [84398] = { "Uno studio sulla Luce", nil, nil, nil, nil, 0xddb1ac83, nil, nil, nil, nil, ".mmmm" },
  [84399] = { "Ka-bum!", nil, nil, nil, nil, 0x41be4c43, nil, nil, nil, nil, ".mmmm" },
  [84400] = { "Il cavaliere e la dama", nil, nil, nil, nil, 0xec2c7ac8, nil, nil, nil, nil, ".mmmm" },
  [84401] = { "Il Flagello: minaccia Non Morta o incompresa?", nil, nil, nil, nil, 0xd1d7a21a, nil, nil, nil, nil, ".mmmm" },
  [84402] = { "Negromanzia 101", nil, nil, nil, nil, 0xaebf1ec4, nil, nil, nil, nil, ".mmmm" },
  [84414] = { "Lasciami andare per la mia strada", "Osserva Orthas mentre lascia questo mondo.", "<Senti la voce disincarnata di Orthas nella tua mente>\n\nEcco fatto, dunque. Procediamo, che dici?", nil, nil, 0x415fa18d, 0x9da87f05, 0xbcfbb7e3, nil, nil, "...mm" },
  [84495] = { "⟦Fiery Plate Gauntlets=Guanti Lunghi a Piastre Ardenti⟧", "Porta a ⟦Malyfous Darkhammer=Malyfous Martelnero⟧ 6 Lingotto di Torio Incantato, 2 ⟦Essence of Fire=Essenza di Fuoco⟧ e 4 Rubino Stellato. Dovrai anche consegnare i tuoi ⟦Unfired Plate Gauntlets=Guanti Lunghi a Piastre Compatte⟧.", "Per la barba di Thaurissan!\n\nDove li hai trovati?\n\nMa soprattutto, sei dispost<o/a> a separartene? Naturalmente ti pagherei per un gesto così nobile.\n\nFacciamo così, {name}. Se mi dai quei guanti compatti, ti insegnerò a farne un paio tutto tuo. Devi solo raccogliere i materiali per me, così potrò mettere a punto la ricetta esatta.\n\nAffare fatto??\n\nEcco la lista di ciò che mi serve. Il torio non incantato lo anticipo io, visto che i guanti li fornisci tu.", nil, nil, 0x4cbb6a5e, 0x87725cc6, 0xccc5a0a0, nil, nil, "...mm" },
  [84550] = { "⟦Codex of Defense=Codice della Difesa⟧", "Restituisci il libro ai suoi legittimi proprietari.", "Il tomo reca il marchio dell'Ateneo.", nil, nil, 0x1bbcdca9, 0xdeb95520, 0x10e08c8e, nil, nil, "...mm" },
  [84555] = { "Il Compendio di Nostro", "Riporta il ⟦Nostro's Compendium of Dragon Slaying=Compendio di Nostro sull'Uccisione dei Draghi⟧ all'Ateneo.", "Hai scoperto qualcosa di grande importanza. Questo libro è diverso da qualsiasi altro tu abbia visto.\n\nSembra che qualcuno o qualcosa sia riuscito a frantumare il sigillo dell'Ateneo. Il testo all'interno è confuso e a malapena leggibile.", nil, nil, 0xd019ffa4, 0x30367b5a, 0x9a80f073, nil, nil, "...mm" },
})
